    { id: "collections-framework", title: "Collections Framework",
      content: "Java Collections: List (ordered, duplicates), Set (no duplicates), Map (key-value). ArrayList vs LinkedList. HashSet vs TreeSet vs LinkedHashSet. HashMap vs TreeMap vs LinkedHashMap. Collections utility class. Iterators. Comparable vs Comparator.",
      code: "import java.util.*;\n\npublic class CollectionsDemo {\n    public static void main(String[] args) {\n        // List — ordered, allows duplicates\n        List<String> list = new ArrayList<>(Arrays.asList(\"B\", \"A\", \"C\", \"A\"));\n        list.add(\"D\");\n        list.sort(Comparator.naturalOrder());\n        System.out.println(\"List: \" + list);  // [A, A, B, C, D]\n\n        // Set — no duplicates\n        Set<String> set = new LinkedHashSet<>(list);\n        System.out.println(\"Set: \" + set);   // [A, B, C, D]\n\n        // TreeSet — sorted, no duplicates\n        TreeSet<String> treeSet = new TreeSet<>(Arrays.asList(\"C\", \"A\", \"B\"));\n        System.out.println(\"Tree: \" + treeSet);  // [A, B, C]\n\n        // Map — key-value pairs\n        Map<String, Integer> map = new HashMap<>();\n        map.put(\"Jay\", 95);\n        map.put(\"Sam\", 88);\n        map.put(\"Alex\", 92);\n        System.out.println(\"Map: \" + map);\n        System.out.println(\"Get Jay: \" + map.get(\"Jay\"));  // 95\n\n        // Iteration\n        for (Map.Entry<String, Integer> entry : map.entrySet()) {\n            System.out.println(entry.getKey() + \" -> \" + entry.getValue());\n        }\n    }\n}",
      keyPoints: ["List: ordered, duplicates allowed", "Set: no duplicates", "Map: key-value pairs", "ArrayList vs LinkedList performance", "HashSet vs TreeSet vs LinkedHashSet", "HashMap vs TreeMap vs LinkedHashMap", "Collections utility class", "Comparable vs Comparator"] }
